      { q: 'When the lists do not intersect:', o: ['Both pointers reach null together and the loop exits', 'It returns the last node', 'It throws', 'The loop never ends'], a: 0, e: 'nullptr == nullptr terminates the loop.' },
      { q: 'Nodes must be compared by:', o: ['Value', 'Identity (pointer)', 'Position', 'Length'], a: 1, e: 'Distinct nodes can hold equal values.' },
      { q: 'The swap must occur when the pointer is:', o: ['Halfway', 'At the last node', 'Null', 'At the head'], a: 2, e: 'Skipping the null step unbalances the distances.' }
